def entry(st, note, by):
    e = {"status": st}
    if note:
        e["note"] = note
    if by:
        e["by"] = by
    return e


changed = 0
for fid, name, st, note, by in UPDATES:
    assert fid in atlas, f"{fid} is not in features.json"
    assert atlas[fid]["name"] == name, f"{fid} is {atlas[fid]['name']!r}, not {name!r}"
    new = entry(st, note, by)
    old = status.get(fid)
    if old != new:
        was = old["status"] if old else "(none)"
        print(f"{fid} {name}: {was} -> {st}")
        status[fid] = new
        changed += 1

if changed:
    json.dump(status, open(T / "rebuild-status.json", "w"), ensure_ascii=False, indent=1)
print(f"{changed} changed; {len(status)} of {len(atlas)} features have a status")
